const surv = [{'id': 0, 'name': '박만수', 'age': 62, 'job': '정비공', 'src': 'sig', 'd': 5, 'region': null, 'hidden': false, 'alias': null, 'hint': null, 'hope': 0, 'need': null, 'match': [1, 9], 'eff': {'craft': 0.25}, 'grade': 0, 'story': ['정비를 끝낸 버스를 시운전하던 밤, 재가 내렸다. 길에서 만난 열한 명을 태우고 대피소까지 달렸다.', '“브레이크 소리만 들어도 차 상태를 알지.” 고장 난 발전기를 한 번 보더니 웃었다.', '승객 명단을 수첩에 적어 다닌다. 아직 세 명밖에 못 찾았다.', '밤마다 운전대를 잡듯 두 손을 모으고 잠든다.', '마을 불빛을 보고 처음으로 “운행 종료”를 외쳤다. 다들 여기 있었구나, 하면서.'], 'trait': '가공할 때 {craft:pc}% 확률로 하나 더'}, {'id': 1, 'name': '강도윤', 'age': 27, 'job': '배달 라이더', 'src': 'sig', 'd': 7.5, 'region': null, 'hidden': false, 'alias': null, 'hint': null, 'hope': 0, 'need': null, 'match': [9], 'eff': {'tap': 0.5}, 'grade': 0, 'story': ['재가 내리던 날에도 마지막 배달을 끝냈다. 받는 사람은 없었지만 문 앞에 두고 왔다.', '골목 지도가 전부 머릿속에 있다. 무너진 길도 돌아가는 길을 안다.', '“배달 완료” 알림음이 가끔 그립다고 했다.', '만수 아저씨 버스를 몇 번이나 추월했었다며 머쓱하게 웃었다.', '이제 이 마을이 자기 배달 주소라고 했다. 그 말이 마음에 든다고.'], 'trait': '두드리는 힘 +{tap:pc}%'}, {'id': 2, 'name': '최서진', 'age': 34, 'job': '응급실 간호사', 'src': 'sig', 'd': 9, 'region': null, 'hidden': false, 'alias': null, 'hint': null, 'hope': 0, 'need': null, 'match': [6, 3], 'eff': {'thrift': 0.12}, 'grade': 1, 'story': ['정전된 병원에서 손전등 하나로 사흘을 버텼다.', '물이 귀해도 손은 꼭 한 번 씻는다. 버릇은 쉽게 안 버려진다.', '마지막으로 돌본 환자의 이름을 묻지 못한 게 아직 마음에 걸린다.', '마을 사람들 맥박을 몰래 재 보는 게 취미가 됐다.', '“여기서는 아무도 혼자 아프지 않을 거예요.” 작은 진료소 간판을 직접 달았다.'], 'trait': '식량 소비 -{thrift:pc}%'}, {'id': 3, 'name': '윤하늘', 'age': 9, 'job': '초등학생', 'src': 'visit', 'd': 0, 'region': null, 'hidden': false, 'alias': null, 'hint': null, 'hope': 12, 'need': null, 'match': [8], 'eff': {'hope': 10}, 'grade': 0, 'story': ['대피하다 할머니 손을 놓쳤다. 노란 우산은 할머니가 사 준 것이다.', '비가 오지 않아도 우산을 편다. 재가 떨어지는 게 무섭다고 했다.', '마을 사람들 이름을 전부 외웠다. 틀리면 처음부터 다시 외운다.', '밤에 랜턴 불빛을 세다 잠든다. 어제는 스물세 개였다.', '“할머니가 불빛 보고 찾아올 거야.” 오늘도 불을 하나 더 켜 달라고 조른다.'], 'trait': '쉘터 희망 +{hope:r}'}, {'id': 4, 'name': '한순례', 'age': 70, 'job': '텃밭 할머니', 'src': 'visit', 'd': 0, 'region': null, 'hidden': false, 'alias': null, 'hint': null, 'hope': 30, 'need': 3, 'match': [2], 'eff': {'food': 0.5}, 'grade': 1, 'story': ['씨앗 봉투 수십 개를 품에 안고 지하에 숨어 있었다.', '봉투마다 이웃 이름이 적혀 있다. 나눠 주려고 받아 둔 씨앗이다.', '손녀 이야기를 할 때만 목소리가 떨린다.', '흙을 쥐어 보고 “아직 살아 있다”고 말했다. 그 말에 다들 조용해졌다.', '노란 우산 옆에 앉아 고추 모종을 심는다. 올해는 꼭 거둘 거라고 한다.'], 'trait': '식량 생산 +{food:pc}%'}, {'id': 5, 'name': '김말순', 'age': 55, 'job': '국밥집 사장', 'src': 'sig', 'd': 11, 'region': null, 'hidden': false, 'alias': null, 'hint': null, 'hope': 0, 'need': null, 'match': [4, 2], 'eff': {'food': 0.3}, 'grade': 1, 'story': ['삼십 년 동안 국밥집을 했다. 재가 내린 날에도 가게 불을 끄지 않았다.', '간을 볼 때 눈을 감는다. 그게 맛의 비결이라고 우긴다.', '단골들 얼굴을 하나하나 그림처럼 기억한다.', '철호 반장이 옛날 단골이었다. 둘은 만나자마자 싸우듯 웃었다.', '“밥은 먹었냐”는 말로 마을 사람들 안부를 챙긴다.'], 'trait': '식량 생산 +{food:pc}%'}, {'id': 6, 'name': '장철호', 'age': 48, 'job': '공사 반장', 'src': 'sig', 'd': 13, 'region': null, 'hidden': false, 'alias': null, 'hint': null, 'hope': 0, 'need': null, 'match': [1, 4], 'eff': {'cost': 0.12}, 'grade': 2, 'story': ['무너지는 현장에서 인부들을 먼저 내보내고 맨 마지막에 나왔다.', '줄자 하나면 어떤 집도 다시 세운다고 큰소리친다.', '종이가 없어 설계도를 벽에 분필로 그린다.', '국밥 한 그릇에 일당을 다 쓰던 시절을 그리워한다.', '마을 첫 아파트 머릿돌에 옛 인부들 이름을 새겼다.'], 'trait': '건설 자재 -{cost:pc}%'}, {'id': 7, 'name': '서유나', 'age': 23, 'job': '미대생', 'src': 'visit', 'd': 0, 'region': null, 'hidden': false, 'alias': null, 'hint': null, 'hope': 50, 'need': null, 'match': [7], 'eff': {'scav': 0.2}, 'grade': 2, 'story': ['졸업 전시를 일주일 앞두고 재가 내렸다.', '숯으로 폐허를 그린다. 그림 속 폐허에는 늘 꽃이 피어 있다.', '하늘이에게 그림을 가르친다. 하늘이는 매번 노란색만 쓴다.', '이 생존자 수첩의 초상화는 사실 전부 유나가 그린 것이다.', '광장에 벽화를 그리는 중이다. 제목은 아직 비밀이다.'], 'trait': '폐허 뒤지기 수확 +{scav:pc}%'}, {'id': 8, 'name': '정우진', 'age': 31, 'job': '소방관', 'src': 'sig', 'd': 15, 'region': null, 'hidden': false, 'alias': null, 'hint': null, 'hope': 0, 'need': null, 'match': [8], 'eff': {'fever': 3}, 'grade': 2, 'story': ['마지막 출동에서 동료를 잃었다. 불을 보면 몸이 먼저 반응한다.', '매일 아침 마을 소화기를 하나씩 점검한다.', '서진 간호사와는 같은 현장에서 몇 번 마주친 사이다.', '랜턴 불꽃을 오래 보다가 “이런 불은 좋네요”라고 말했다.', '아이들에게 불 끄는 법 대신 불 지키는 법을 가르친다.'], 'trait': '랜턴 피버 +{fever:f1}초'}, {'id': 9, 'name': '오재혁', 'age': 41, 'job': '발전소 연구원', 'src': 'sig', 'd': 12, 'region': null, 'hidden': false, 'alias': null, 'hint': null, 'hope': 0, 'need': null, 'match': [5, 7], 'eff': {'global': 0.2}, 'grade': 2, 'story': ['재가 시작된 날, 그는 발전소 제어실에 있었다.', '밤마다 무언가를 계산한다. 누가 들여다보면 종이를 덮는다.', '일기 속 “조용한 굴뚝” 이야기를 듣고 한참 말이 없었다.', '“멈추라고 했어요. 아무도 듣지 않았죠.” 처음으로 그날 이야기를 꺼냈다.', '재를 녹일 빛을 다시 켜는 법이 발전소에 있다고 믿는다. 다음 이야기의 문이 열린다.'], 'trait': '모든 생산 +{global:pc}%'}, {'id': 10, 'name': '차은호', 'age': 36, 'job': '심야 라디오 DJ', 'src': 'story', 'd': 0, 'region': null, 'hidden': true, 'alias': '목소리의 주인', 'hint': '4장, 라디오 속 목소리를 따라 찾아와요', 'hope': 0, 'need': null, 'match': [7, 8], 'eff': {'hope': 8, 'scav': 0.1}, 'grade': 3, 'story': ['하늘이 얕은 밤에만 마이크를 켠다. 청취자가 한 명이라도 있을지 몰라서.', '“여기는 심야 방송 한밤입니다.” 우리 라디오에 처음 잡힌 방송이 그였다.', '아무도 보내지 않은 신청곡 쪽지를 모은다. 하늘이 얕은 밤이면 한 곡씩 튼다.', '하늘이가 사연을 보냈다. “우리 할머니 찾아 주세요.” 그는 그날 방송을 세 번 반복했다.', '“이제 방송국은 여기예요.” 쉘터 한가운데에 낡은 스피커를 달았다.'], 'trait': '희망 +{hope:r} · 뒤지기 수확 +{scav:pc}%'}, {'id': 11, 'name': '백설화', 'age': 29, 'job': '전 기상캐스터', 'src': 'gacha', 'd': 0, 'region': null, 'hidden': true, 'alias': '날씨를 아는 사람', 'hint': null, 'hope': 0, 'need': null, 'match': [3, 8], 'eff': {'tap': 0.35, 'fever': 1.5}, 'grade': 3, 'story': ['재가 내리기 전날, 그녀는 “내일은 맑겠습니다”라고 방송했다.', '구름이 이상했지만, 발표 직전 위에서 원고가 바뀌어 내려왔다. 그 한마디가 평생의 한이 됐다.', '지금은 하늘 색만 보고 재폭풍이 몇 시에 올지 맞힌다. 한 번도 틀린 적이 없다.', '은호의 라디오에서 예전 자기 목소리가 흘러나오자 한참을 울었다.', '“내일은 맑겠습니다.” 이번엔 정말로 맑았다.'], 'trait': '두드리는 힘 +{tap:pc}% · 랜턴 피버 +{fever:f1}초'}, {'id': 12, 'name': '문태식', 'age': 77, 'job': '시계공', 'src': 'gacha', 'd': 0, 'region': null, 'hidden': true, 'alias': '멈춘 시계를 든 노인', 'hint': null, 'hope': 0, 'need': null, 'match': [1, 5], 'eff': {'craft': 0.35, 'cost': 0.06}, 'grade': 3, 'story': ['멈춘 시계 백 개를 짊어지고 걸어왔다. 전부 재가 내린 시각, 3시 14분에 멈춰 있다.', '하나를 고칠 때마다 누군가의 시간이 다시 흐르는 거라고 믿는다.', '만수의 버스 시계를 고쳐 주었다. 둘은 밤새 옛 노선 이야기를 했다.', '시계 하나가 3시 14분을 지나 움직이기 시작했다. 쉘터 사람들이 모여 박수를 쳤다.', '“시간은 다시 가요. 우리가 태엽을 감는 한.”'], 'trait': '가공할 때 {craft:pc}% 확률로 하나 더 · 건설 자재 -{cost:pc}%'}, {'id': 13, 'name': '탁미영', 'age': 41, 'job': '발전소 제어실 운전원', 'src': 'deep', 'd': 0, 'region': null, 'hidden': true, 'alias': '가장 깊은 곳의 운전원', 'hint': null, 'hope': 0, 'need': null, 'match': [5, 7], 'eff': {'craft': 0.25, 'hope': 6}, 'grade': 3, 'story': ['재가 내리던 새벽, 제어실에서 마지막까지 버튼을 누르고 있던 사람.', '처음엔 동료 몇 명과 함께였다. 하나둘 재의 벽을 넘다 돌아오지 못했고, 그녀는 끝까지 심지 곁에 남았다. 쉘터에 와서도 심지를 품에 안고 잔다.', '“재는 제 탓이에요.” 처음 쉘터에 온 날 밤, 그녀는 한숨도 자지 못했다. 그날 끊긴 수화기를 몇 번이고 다시 들었다고 했다.', '재혁과 밤새 도면을 펼쳐 놓고 이야기했다. 둘 다 같은 걸 꿈꾸고 있었다. 재를 녹일 빛.', '“이번엔 제대로 켤 거예요.” 그녀가 발전기 스위치를 올리자, 쉘터 전체가 환해졌다.'], 'trait': '가공할 때 {craft:pc}% 확률로 하나 더 · 희망 +{hope:r}'}, {'id': 14, 'name': '한별', 'age': 32, 'job': '사막 약초 약사', 'src': 'region', 'd': 0, 'region': 'desert', 'hidden': true, 'alias': '신기루 속의 약사', 'hint': '메마른 사막 도시에서, 동네 목표를 두 개 넘기면 신호가 보여요', 'hope': 0, 'need': null, 'match': [6, 2], 'eff': {'thrift': 0.15, 'hope': 4}, 'grade': 3, 'story': ['모래바람 속에서 천막 약방을 지키던 사람. 선인장 즙으로 해열제를 만든다.', '“약은 떨어져도 약초는 자라요.” 그녀의 가방엔 씨앗이 약보다 많다.', '두식 할아버지의 무릎은 그녀가 아니었으면 진작 굳었을 거라고 한다.', '서진과 밤새 약병 라벨을 새로 썼다. 두 사람 글씨가 번갈아 적혀 있다.', '사막여우 모래알이 그녀 발치에서 잠든다. 둘은 원래 한 식구였다.'], 'trait': '식량 소비 -{thrift:pc}% · 희망 +{hope:r}'}, {'id': 15, 'name': '도진', 'age': 38, 'job': '공단 용접공', 'src': 'region', 'd': 0, 'region': 'factory', 'hidden': true, 'alias': '불꽃을 다루는 사람', 'hint': '녹슨 공단 지대에서, 동네 목표를 두 개 넘기면 신호가 보여요', 'hope': 0, 'need': null, 'match': [1, 5], 'eff': {'craft': 0.3, 'cost': 0.06}, 'grade': 3, 'story': ['공단이 멈춘 날에도 용접 불꽃을 끄지 않았다. 불꽃이 곧 불빛이었으니까.', '말수가 적다. 대신 망가진 건 말없이 고쳐 둔다.', '딸아이가 만든 과학 숙제, 강아지 로봇을 찾아 공단을 헤맸다고 했다.', '철호 반장과 쇠 두드리는 박자가 똑같다. 둘이 일하면 공장 소리가 난다.', '볼트의 새 다리는 그가 밤새 깎은 것이다.'], 'trait': '가공할 때 {craft:pc}% 확률로 하나 더 · 건설 비용 -{cost:pc}%'}, {'id': 16, 'name': '설아', 'age': 26, 'job': '산악 구조대원', 'src': 'region', 'd': 0, 'region': 'snow', 'hidden': true, 'alias': '눈 속의 구조대원', 'hint': '눈 덮인 산골 마을에서, 동네 목표를 두 개 넘기면 신호가 보여요', 'hope': 0, 'need': null, 'match': [8, 3], 'eff': {'tap': 0.3, 'scav': 0.1}, 'grade': 3, 'story': ['눈사태 속에서 아이 셋을 업고 내려왔다. 그 뒤로 산을 떠나지 않았다.', '로프 매듭 스무 가지를 눈 감고도 묶는다. 분교 아이들이 제일 먼저 배웠다.', '우진과는 첫날부터 말이 잘 통했다. “현장”이라는 말 하나로.', '반달이를 처음 발견한 것도 그녀다. 어미 곰 발자국을 끝까지 따라갔다고 한다.', '“구조는 끝나지 않아요. 다음 사람이 있으니까.”'], 'trait': '두드리는 힘 +{tap:pc}% · 뒤지기 수확 +{scav:pc}%'}, {'id': 17, 'name': '진', 'age': 15, 'job': '전 까마귀 정찰병', 'src': 'story', 'd': 0, 'region': null, 'hidden': true, 'alias': '검은 새 표식의 아이', 'hint': '까마귀 무리와 마주친 뒤에 만날 수 있어요', 'hope': 0, 'need': null, 'match': [9, 4], 'eff': {'scav': 0.15, 'tap': 0.2}, 'grade': 2, 'story': ['재폭풍 속에서 가족과 흩어졌다. 혼자 떠돌던 그를 까마귀가 거뒀다. 무리에서 제일 어렸고, 제일 먼저 뛰고, 제일 늦게 먹었다.', '팔뚝의 검은 새 표식을 소매로 가린다. 아무도 묻지 않아도.', '하늘이가 처음으로 먼저 말을 걸었다. “오빠, 우산 같이 쓸래?”', '독수리 대장 이야기가 나오면 입을 다문다. 미워하지도, 그리워하지도 못하는 얼굴로.', '“여기선 불을 켜도 되는 거죠?” 처음으로 랜턴을 제 손으로 켰다.'], 'trait': '뒤지기 수확 +{scav:pc}% · 두드리는 힘 +{tap:pc}%'}, {'id': 18, 'name': '고수현', 'age': 34, 'job': '항만 정비창 정비사', 'src': 'town', 'd': 7, 'region': 'desert', 'hidden': false, 'alias': null, 'hint': '메마른 사막 도시에서 구조 신호로 만나요', 'hope': 0, 'need': null, 'match': [1, 5], 'eff': {'craft': 0.2}, 'grade': 1, 'story': ['모래에 묻힌 정비창을 혼자 파내며 버텼다.', '기계 소리만 들으면 어디가 고장인지 안다고 한다.', '“고치면 다시 돌아요. 사람도 그렇고요.”'], 'trait': '가공할 때 {craft:pc}% 확률로 하나 더'}, {'id': 19, 'name': '마리아', 'age': 29, 'job': '오아시스 식당 요리사', 'src': 'town', 'd': 8, 'region': 'desert', 'hidden': false, 'alias': null, 'hint': '메마른 사막 도시에서 구조 신호로 만나요', 'hope': 0, 'need': null, 'match': [2, 4], 'eff': {'food': 0.25}, 'grade': 0, 'story': ['물이 마른 오아시스 식당에서 마지막 손님까지 밥을 지었다.', '향신료 통을 아직 버리지 않았다.', '“먹을 게 있으면 사람은 안 떠나요.”'], 'trait': '식량 생산 +{food:pc}%'}, {'id': 20, 'name': '바위', 'age': 52, 'job': '화물 트럭 짐꾼', 'src': 'town', 'd': 9, 'region': 'desert', 'hidden': false, 'alias': null, 'hint': '메마른 사막 도시에서 구조 신호로 만나요', 'hope': 0, 'need': null, 'match': [9, 4], 'eff': {'scav': 0.15}, 'grade': 0, 'story': ['트럭 행렬이 흩어진 뒤에도 짐은 버리지 않았다.', '등에 진 자루에는 남의 물건만 들어 있다. 돌려줄 생각이다.', '“짐은 주인한테 가야지.” 그것 말고는 말이 없다.'], 'trait': '폐허 뒤지기 수확 +{scav:pc}%'}, {'id': 21, 'name': '유나래', 'age': 23, 'job': '등대 조수', 'src': 'town', 'd': 10, 'region': 'desert', 'hidden': false, 'alias': null, 'hint': '메마른 사막 도시에서 구조 신호로 만나요', 'hope': 0, 'need': null, 'match': [7, 3], 'eff': {'hope': 5, 'scav': 0.05}, 'grade': 1, 'story': ['불 꺼진 등대 꼭대기에서 매일 바다 쪽을 적었다.', '등대 렌즈를 혼자 닦아 두었다. 언젠가 켜질 거라고.', '“불빛은 누가 보고 있는지 몰라도 켜 두는 거예요.”'], 'trait': '희망 +{hope:r} · 뒤지기 수확 +{scav:pc}%'}, {'id': 22, 'name': '강태오', 'age': 41, 'job': '프레스 공장 반장', 'src': 'town', 'd': 7, 'region': 'factory', 'hidden': false, 'alias': null, 'hint': '녹슨 공단 지대에서 구조 신호로 만나요', 'hope': 0, 'need': null, 'match': [1, 9], 'eff': {'craft': 0.15, 'cost': 0.05}, 'grade': 1, 'story': ['멈춘 프레스 기계 사이에서 사람들을 밖으로 내보냈다.', '손끝에 기름때가 지워지지 않는다.', '“기계는 사람이 돌리는 거야.”'], 'trait': '가공할 때 {craft:pc}% 확률로 하나 더 · 건설 자재 -{cost:pc}%'}, {'id': 23, 'name': '이보라', 'age': 27, 'job': '공단 구내식당 영양사', 'src': 'town', 'd': 8, 'region': 'factory', 'hidden': false, 'alias': null, 'hint': '녹슨 공단 지대에서 구조 신호로 만나요', 'hope': 0, 'need': null, 'match': [2, 6], 'eff': {'thrift': 0.1, 'hope': 3}, 'grade': 0, 'story': ['식당 냉장고가 멈춘 뒤에도 배급표를 만들었다.', '아무도 두 번 받지 못하게, 아무도 굶지 않게.', '“나눠 먹으면 모자라도 괜찮아요.”'], 'trait': '식량 소비 -{thrift:pc}% · 희망 +{hope:r}'}, {'id': 24, 'name': '노민재', 'age': 19, 'job': '배선 견습공', 'src': 'town', 'd': 9, 'region': 'factory', 'hidden': false, 'alias': null, 'hint': '녹슨 공단 지대에서 구조 신호로 만나요', 'hope': 0, 'need': null, 'match': [5, 8], 'eff': {'tap': 0.2}, 'grade': 0, 'story': ['견습 첫 달에 재가 내렸다.', '선배들이 남긴 배선도를 외우며 버텼다.', '“전기는 겁내면 안 돼요. 존중해야죠.”'], 'trait': '두드리는 힘 +{tap:pc}%'}, {'id': 25, 'name': '한정숙', 'age': 58, 'job': '공단 보건실 간호조무사', 'src': 'town', 'd': 10, 'region': 'factory', 'hidden': false, 'alias': null, 'hint': '녹슨 공단 지대에서 구조 신호로 만나요', 'hope': 0, 'need': null, 'match': [6, 3], 'eff': {'hope': 6}, 'grade': 1, 'story': ['보건실 약장을 비우지 않고 지켰다.', '다친 사람 이름을 전부 수첩에 적어 두었다.', '“아픈 데 없는 사람은 없어요. 말을 안 할 뿐이지.”'], 'trait': '쉘터 희망 +{hope:r}'}, {'id': 26, 'name': '박설', 'age': 31, 'job': '산장 관리인', 'src': 'town', 'd': 7, 'region': 'snow', 'hidden': false, 'alias'